from fastmcp.server import FastMCP

# Create the sub-server with math tools
math_server = FastMCP(name="math_server")

@math_server.tool
def add(a: int, b: int) -> int:
    """Add two numbers."""
    return a + b

@math_server.tool
def subtract(a: int, b: int) -> int:
    """Subtract two numbers."""
    return a - b

@math_server.tool
def multiply(a: int, b: int) -> int:
    """Multiply two numbers."""
    return a * b

@math_server.tool
def divide(a: float, b: float) -> float:
    """Divide two numbers."""
    if b == 0:
        raise ValueError("Cannot divide by zero")
    return a / b

# Create the main server
main_server = FastMCP(name="main_server")

@main_server.tool
def greet(name: str) -> str:
    """Greet someone."""
    return f"Hello, {name}!"

# Mount the math server under the "math" namespace
main_server.mount(math_server, namespace="math")

# Run the main server
if __name__ == "__main__":
    main_server.run()
